<?php require __DIR__ . '/menu.php'; ?><!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Conta — ZystemWorkSpace</title><style>body{font:15px system-ui;background:#080d14;color:#e8eef7;max-width:700px;margin:8vh auto;padding:18px}section{background:#101a28;border:1px solid #29405d;border-radius:12px;padding:20px;margin-bottom:14px}button{padding:11px;background:#315f91;color:#fff;border:0;border-radius:7px;cursor:pointer}button.danger{background:#7a3040}input{display:block;width:100%;box-sizing:border-box;padding:10px;margin:8px 0;border-radius:7px;border:1px solid #385474;background:#0b1420;color:#e8eef7}.muted{color:#91a5bc}.status{min-height:22px;color:#9fe0b0}.error{color:#ff9d9d}a{color:#a9d5ff}</style><section><h1>Minha conta</h1><div id="user">Carregando...</div><p><a href="index.php">Chat</a> · <a href="login.php">Trocar acesso</a></p><button class="danger" id="logout">Sair da conta</button></section><section><h2>Alterar senha</h2><p class="muted">A sessão temporária não possui senha. Para contas permanentes, informe a senha atual e uma nova senha com pelo menos 8 caracteres.</p><form id="password"><input name="current_password" type="password" placeholder="Senha atual" required><input name="new_password" type="password" minlength="8" placeholder="Nova senha — mínimo 8 caracteres" required><button>Alterar senha</button></form><div id="msg" class="status"></div></section><script>const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));fetch('../api/auth.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'me'})}).then(r=>r.json()).then(d=>{const u=d.user||{};$('#user').innerHTML=`<p><b>Nome:</b> ${esc(u.display_name||'Usuário temporário')}</p><p><b>Usuário:</b> ${esc(u.username||'não informado')}</p><p><b>E-mail:</b> ${esc(u.email||'não informado')}</p><p><b>Perfil:</b> ${esc(u.role||'guest')}</p><p><b>Tipo:</b> ${u.temporary?'sessão temporária':'conta permanente'}</p>`});$('#password').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),m=$('#msg');try{const r=await fetch('../api/auth.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'change_password',current_password:f.get('current_password'),new_password:f.get('new_password')})}),d=await r.json();if(!d.ok)throw Error(d.error);m.textContent='Senha alterada com sucesso.';e.target.reset()}catch(x){m.textContent=x.message;m.className='status error'}};$('#logout').onclick=async()=>{await fetch('../api/auth.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});location.href='login.php'}</script>
